package com.collegeerp.erp.email.config; import org.springframework.context.annotation.*; import org.springframework.scheduling.annotation.*; import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor; import java.util.concurrent.Executor;
@Configuration @EnableAsync @EnableScheduling public class EmailAsyncConfiguration {@Bean(name="emailTaskExecutor") Executor executor(){ThreadPoolTaskExecutor e=new ThreadPoolTaskExecutor();e.setCorePoolSize(2);e.setMaxPoolSize(5);e.setQueueCapacity(200);e.setThreadNamePrefix("email-worker-");e.setWaitForTasksToCompleteOnShutdown(true);e.setAwaitTerminationSeconds(30);e.initialize();return e;}}
